<?php declare(strict_types=1);namespace App\Services;use App\Core\Config;use App\Core\Crypto;use App\Core\DB;use App\Core\Mailer;use App\Models\AuditLog;use App\Models\License;use App\Models\Plan;use App\Models\User;final class LicenseService{public static function create(int $u,array $e,string $Z='month',?int $U=null,?int $f=null,array $q=[]):array{$f=$f??($Z==='year'?12:1);$b=new \DateTimeImmutable('now',new \DateTimeZone('UTC'));$d=$b->modify('+'.$f.' months')->setTime(23,59,59);if($e['slug']==='trial'){$d=$b->modify('+'.(int)($e['trial_days']?:Config::get('license.trial_days',14)).' days')->setTime(23,59,59);}do{$S=Crypto::generateLicenseKey();}while(License::findByKey($S));$C=array_merge(['user_id'=>$u,'plan_id'=>(int)$e['id'],'order_id'=>$U,'license_key'=>$S,'status'=>'active','period'=>$Z,'starts_at'=>$b->format('Y-m-d H:i:s'),'expires_at'=>$d->format('Y-m-d H:i:s'),'max_cameras'=>$e['max_cameras'],'max_activations'=>1,'features'=>$e['features']??[],'auto_renew'=>$e['slug']!=='trial'?1:0],$q);$i=License::create($C);License::logEvent($i,'created',['plan'=>$e['slug'],'period'=>$Z,'expires_at'=>$C['expires_at']]);AuditLog::log('license.create',$S,['user_id'=>$u,'plan'=>$e['slug']]);return License::find($i);}public static function extend(array $X,int $d,?int $G=null):array{$L=max(time(),strtotime((string)$X['expires_at'])?:time());$r=(new \DateTimeImmutable('@'.$L))->modify('+'.$d.' months')->setTime(23,59,59);$x=['expires_at'=>$r->format('Y-m-d H:i:s'),'reminder_sent_at'=>null,'expiry_sent_at'=>null];if(in_array($X['status'],['expired'],true)){$x['status']='active';}License::update((int)$X['id'],$x);License::logEvent((int)$X['id'],'renewed',['months'=>$d,'expires_at'=>$x['expires_at'],'order_id'=>$G]);return License::find((int)$X['id']);}public static function changePlan(array $p,array $i,string $W,?int $h=null,bool $n=true):array{License::update((int)$p['id'],['plan_id'=>(int)$i['id'],'max_cameras'=>$i['max_cameras'],'features'=>$i['features'],'period'=>$W,'status'=>'active']);License::logEvent((int)$p['id'],'plan_changed',['plan'=>$i['slug'],'order_id'=>$h]);$m=License::find((int)$p['id']);if($n){$m=self::extend($m,$W==='year'?12:1,$h);}return $m;}public static function setStatus(array $H,string $U,string $q=''):void{if(!in_array($U,License::STATUSES,true)){throw new \InvalidArgumentException('Statut invalide');}License::update((int)$H['id'],['status'=>$U]);License::logEvent((int)$H['id'],'status_'.$U,['reason'=>$q]);AuditLog::log('license.'.$U,$H['license_key'],['reason'=>$q]);}public static function features(array $E):array{$w=$E['features'];if(is_string($w)){$w=json_decode($w,true)?:[];}return array_values(array_unique(array_map('strval',(array)$w)));}public static function toApi(array $E,?array $y=null,?array $g=null):array{$y=$y??Plan::find((int)$E['plan_id']);$g=$g??User::find((int)$E['user_id']);return['key'=>$E['license_key'],'plan'=>$y['slug']??'unknown','status'=>License::effectiveStatus($E),'expires_at'=>gmdate('Y-m-d\TH:i:s\Z',strtotime((string)$E['expires_at'])?:0),'max_cameras'=>$E['max_cameras']===null?9999:(int)$E['max_cameras'],'features'=>self::features($E),'customer'=>$g?User::displayName($g):''];}public static function issueToken(array $E,string $y,?array $M=null):string{$M=$M??Plan::find((int)$E['plan_id']);return Crypto::signedToken(['key'=>$E['license_key'],'plan'=>$M['slug']??'unknown','machine_id'=>$y,'expires_at'=>gmdate('Y-m-d\TH:i:s\Z',strtotime((string)$E['expires_at'])?:0),'max_cameras'=>$E['max_cameras']===null?9999:(int)$E['max_cameras'],'features'=>self::features($E),'issued_at'=>gmdate('Y-m-d\TH:i:s\Z'),'grace_days'=>(int)Config::get('license.grace_days',7)]);}public static function activate(string $u,string $e,?string $i,?string $D,string $G,bool $y=false):array{$m=Crypto::normalizeLicenseKey($u);if($m===null||!preg_match('/^[a-f0-9]{64}$/i',$e)){return['ok'=>false,'error'=>'invalid_key','status'=>400];}$o=License::findByKey($m);if(!$o){return['ok'=>false,'error'=>'invalid_key','status'=>404];}$s=License::effectiveStatus($o);if($s==='revoked'){return['ok'=>false,'error'=>'revoked','status'=>403];}if($s==='suspended'){return['ok'=>false,'error'=>'suspended','status'=>403];}if($s==='expired'){if($o['status']==='active'){License::update((int)$o['id'],['status'=>'expired']);}return['ok'=>false,'error'=>'expired','status'=>403];}$e=strtolower($e);$g=DB::from('activations')->where('license_id',(int)$o['id'])->where('machine_id',$e)->where('revoked_at',null)->first();if(!$g){$B=License::activeActivationCount((int)$o['id']);if($B>=(int)$o['max_activations']){if($y){return['ok'=>false,'error'=>'activation_limit','status'=>409];}return['ok'=>false,'error'=>'activation_limit','status'=>409];}DB::insert('activations',['license_id'=>(int)$o['id'],'machine_id'=>$e,'hostname'=>$i,'version'=>$D,'ip'=>$G,'activated_at'=>now(),'last_seen_at'=>now()]);License::logEvent((int)$o['id'],'activated',['machine_id'=>$e,'hostname'=>$i,'version'=>$D],$G);}else{DB::update('activations',['hostname'=>$i??$g['hostname'],'version'=>$D??$g['version'],'ip'=>$G,'last_seen_at'=>now()],'id = ?',[$g['id']]);if($y){License::logEvent((int)$o['id'],'heartbeat',['machine_id'=>$e,'version'=>$D],$G);}}$C=Plan::find((int)$o['plan_id']);return['ok'=>true,'token'=>self::issueToken($o,$e,$C),'license'=>self::toApi($o,$C)];}public static function deactivate(string $j,string $b,string $s):array{$k=Crypto::normalizeLicenseKey($j);if($k===null){return['ok'=>false,'error'=>'invalid_key','status'=>400];}$l=License::findByKey($k);if(!$l){return['ok'=>false,'error'=>'invalid_key','status'=>404];}$f=DB::update('activations',['revoked_at'=>now()],'license_id = ? AND machine_id = ? AND revoked_at IS NULL',[(int)$l['id'],strtolower($b)]);License::logEvent((int)$l['id'],'deactivated',['machine_id'=>$b,'found'=>$f>0],$s);return['ok'=>true,'deactivated'=>$f>0];}public static function revokeActivation(int $H,int $W,string $R='user'):bool{$r=DB::update('activations',['revoked_at'=>now()],'id = ? AND license_id = ? AND revoked_at IS NULL',[$H,$W]);if($r){License::logEvent($W,'activation_revoked',['activation_id'=>$H,'by'=>$R]);}return $r>0;}public static function expireOverdue():int{$D=DB::fetchAll('SELECT id, license_key FROM {{licenses}} WHERE status = ? AND expires_at < ?',['active',now()]);foreach($D as $k){License::update((int)$k['id'],['status'=>'expired']);License::logEvent((int)$k['id'],'status_expired',['auto'=>true]);}return count($D);}public static function sendRenewalReminders(int $t=7):int{$O=now();$I=gmdate('Y-m-d H:i:s',time()+$t*86400);$Y=DB::fetchAll('SELECT l.*, u.email, u.lang, u.name FROM {{licenses}} l JOIN {{users}} u ON u.id = l.user_id JOIN {{plans}} p ON p.id = l.plan_id WHERE l.status = ? AND l.expires_at BETWEEN ? AND ? AND l.reminder_sent_at IS NULL AND p.slug <> ?',['active',$O,$I,'trial']);$c=new Mailer();$i=0;foreach($Y as $o){$c->sendTemplate($o['email'],'renewal_reminder',['user'=>$o,'license'=>$o,'days'=>$t],$o['lang']?:'fr',$o['name']);License::update((int)$o['id'],['reminder_sent_at'=>now()]);$i++;}return $i;}public static function sendExpiryNotices():int{$z=DB::fetchAll('SELECT l.*, u.email, u.lang, u.name FROM {{licenses}} l JOIN {{users}} u ON u.id = l.user_id WHERE l.status = ? AND l.expiry_sent_at IS NULL',['expired']);$a=new Mailer();$g=0;foreach($z as $Q){$a->sendTemplate($Q['email'],'expiry',['user'=>$Q,'license'=>$Q],$Q['lang']?:'fr',$Q['name']);License::update((int)$Q['id'],['expiry_sent_at'=>now()]);$g++;}return $g;}public static function stats():array{$now=now();$active=(int)DB::scalar('SELECT COUNT(*) FROM {{licenses}} WHERE status = ? AND expires_at >= ?',['active',$now]);$activations=(int)DB::scalar('SELECT COUNT(*) FROM {{activations}} WHERE revoked_at IS NULL');$mrr=(int)DB::scalar('SELECT COALESCE(SUM(CASE WHEN l.period = ? THEN p.price_year / 12 ELSE p.price_month END), 0) FROM {{licenses}} l JOIN {{plans}} p ON p.id = l.plan_id WHERE l.status = ? AND l.expires_at >= ? AND p.slug <> ?',['year','active',$now,'trial']);$sales30=(int)DB::scalar('SELECT COALESCE(SUM(total), 0) FROM {{orders}} WHERE status = ? AND paid_at >= ?',['paid',gmdate('Y-m-d H:i:s',time()-30*86400)]);$orders30=(int)DB::scalar('SELECT COUNT(*) FROM {{orders}} WHERE status = ? AND paid_at >= ?',['paid',gmdate('Y-m-d H:i:s',time()-30*86400)]);$customers=(int)DB::scalar('SELECT COUNT(*) FROM {{users}} WHERE role = ?',['customer']);$trials=(int)DB::scalar('SELECT COUNT(*) FROM {{licenses}} l JOIN {{plans}} p ON p.id = l.plan_id WHERE p.slug = ? AND l.status = ? AND l.expires_at >= ?',['trial','active',$now]);return compact('active','activations','mrr','sales30','orders30','customers','trials');}}